import { promises as fs } from 'node:fs'
import { dirname, resolve } from 'pathe'
import type { DurationObservation } from './duration-smoothing'

export type DurationHistory = Record<string, DurationObservation[]>

export async function readDurationHistory(root: string, path: string, ttl: number): Promise<DurationHistory | null> {
  try {
    const input = JSON.parse(await fs.readFile(resolve(root, path), 'utf8'))
    if (!input || typeof input !== 'object' || Array.isArray(input)) return null
    const cutoff = ttl > 0 ? Date.now() - ttl : 0
    const output: DurationHistory = {}
    for (const [file, value] of Object.entries(input)) {
      const observations = typeof value === 'number'
        ? [{ duration: value, recordedAt: 0 }]
        : value && typeof value === 'object' && !Array.isArray(value)
          ? 'observations' in value && Array.isArray(value.observations) ? value.observations : [value]
          : null
      if (!observations || observations.some(item => !item || typeof item.duration !== 'number' || !Number.isFinite(item.duration) || typeof item.recordedAt !== 'number' || !Number.isFinite(item.recordedAt))) return null
      output[file] = observations.filter(item => item.recordedAt === 0 || item.recordedAt >= cutoff)
    }
    return output
  }
  catch {
    return null
  }
}

export async function writeDurationHistory(root: string, path: string, history: DurationHistory, maxRuns: number): Promise<void> {
  const target = resolve(root, path)
  await fs.mkdir(dirname(target), { recursive: true })
  const output = Object.fromEntries(Object.entries(history).map(([file, observations]) => {
    const recent = [...observations].sort((a, b) => b.recordedAt - a.recordedAt).slice(0, maxRuns)
    return [file, maxRuns === 1 ? (recent[0] || { duration: 0, recordedAt: 0 }) : { observations: recent }]
  }))
  await fs.writeFile(target, JSON.stringify(output, null, 2))
}

